        float2 uv = streams.TexCoord;

        float2 fromCenterVector = uv - new float2(0.5f, 0.5f);
        float squareDistanceToCenter = dot(fromCenterVector, fromCenterVector);
        float distanceToCenter = sqrt(squareDistanceToCenter);

